const o = $input.first().json;
const r = o.result || {};
const morning = o.mode === 'morning';
const day = String(r.now_cairo || '').slice(0, 10);
const dl = (s) => !s ? '' : (String(s).endsWith('23:59') ? String(s).slice(0, 10) : String(s));
const pri = { urgent: '🔴', high: '🟠', medium: '🟡', low: '⚪' };
const stateAr = { PROPOSAL_DRAFTED: 'مسودة جاهزة', PROPOSAL_SUBMITTED: 'اتقدّم' };
const lim = (a, n = 8) => (Array.isArray(a) ? a : []).slice(0, n);
const taskLine = (t, i) => `${i + 1}. ${pri[t.priority] || ''} ${t.title}${t.deadline_cairo ? ' — ' + dl(t.deadline_cairo) : ''}`.replace('  ', ' ');
const out = [];
out.push(morning ? `أهلاً يا ${o.display_name || 'محمد'} 👋 ملخص يومك (${day})` : `🌙 مراجعة آخر اليوم (${day})`);
const sec = (title, lines) => { if (lines.length) { out.push('', title, ...lines); } };

if (morning) {
  sec('📅 مواعيد اليوم:', lim((r.today_schedule || []).filter(s => !['sleep','rest','break'].includes(String(s.session_type || '').toLowerCase())), 10).map(s => `- ${String(s.start_cairo).slice(11, 16)}–${String(s.end_cairo).slice(11, 16)} ${s.title}`));
  sec('⏰ متأخر:', lim(r.tasks_overdue).map(t => `- ${t.title} (${dl(t.deadline_cairo)})`));
  sec('✅ تاسكات اليوم:', lim(r.tasks_today).map(taskLine));
  sec('📌 ديدلاينز الأسبوع:', lim(r.upcoming_deadlines).map(x => `- ${x.title}: ${dl(x.due_cairo)}${x.is_hard ? ' (ثابت)' : ''}`));
  sec('💼 شغلانات جديدة مناسبة:', lim(r.new_opportunities, 5).map(x => `- ${x.code} ${x.title} (${Math.round(x.match_score)}%) — قول: بروبوزال ${x.code}`));
  sec('📝 بروبوزالات للمتابعة:', lim(r.proposal_follow_up).map(x => `- ${x.code} ${x.title} (${stateAr[x.state] || x.state}، آخر تحديث ${x.last_update})`));
} else {
  sec('✅ لسه متبقي النهارده:', lim(r.tasks_today).map(taskLine));
  sec('⏰ متأخر:', lim(r.tasks_overdue).map(t => `- ${t.title} (${dl(t.deadline_cairo)})`));
  sec('➡️ بكرة:', lim(r.tasks_tomorrow).map(taskLine));
  sec('💼 فرص مفتوحة:', lim(r.new_opportunities, 5).map(x => `- ${x.code} ${x.title} (${Math.round(x.match_score)}%)`));
  sec('📝 بروبوزالات للمتابعة:', lim(r.proposal_follow_up).map(x => `- ${x.code} ${x.title} (${stateAr[x.state] || x.state})`));
}
if (out.length === 1) out.push('', 'مفيش حاجة مسجلة عندي دلوقتي 👌');
if (!morning) out.push('', 'ارتاح، وبكرة يوم جديد 🌿');
return [{ json: { telegram_id: o.telegram_id, text: out.join('\n').slice(0, 3900) } }];

// EDIT THIS LIST any time (no new import needed). Public listing pages only, read-only.
// 'pattern' = text that individual job links contain.
// Not included on purpose: Upwork (blocks bots: use its email alerts + Mail Watcher), Fiverr (not a job board),
// Nafezly (did not answer) and Kafiil (add them here when you have a working "new projects" page URL).
const SITES = [
  { name: 'Mostaql',    url: 'https://mostaql.com/projects',            base: 'https://mostaql.com',         pattern: '/project/' },
  { name: 'Khamsat',    url: 'https://khamsat.com/community/requests',  base: 'https://khamsat.com',         pattern: '/community/requests/' },
  { name: 'Freelancer', url: 'https://www.freelancer.com/jobs/',        base: 'https://www.freelancer.com',  pattern: '/projects/' }
];
return SITES.map(s => ({ json: s }));

const KEYWORDS = ['.net','asp','c#','csharp','sql','database','قاعدة بيانات','قواعد بيانات','موقع','مواقع','ويب','web','website','برمجة','مبرمج','برمجي','تطبيق','api','backend','full stack','network','شبكة','شبكات','cisco','packet tracer','vlan','security','أمن','امن','سيبراني','linux','لينكس','wordpress','ووردبريس','متجر','php','laravel','react','javascript','python','سيرفر','vps','هوستنج','devops','docker','git','سكربت','script','بوت','bot','automation','اتمتة','n8n','نظام','developer','software','app'];
const STRONG = ['.net','asp','c#','sql','network','شبكة','شبكات','cisco','packet tracer','vlan','security','سيبراني','full stack','قاعدة بيانات','قواعد بيانات'];
const MAX_PER_SITE = 8, MAX_BASELINE = 60;
const sites = $('Sites').all();
const owner = $('Known Counts').first().json;
const counts = owner.counts || {};
const decode = (s) => s.replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&nbsp;/g,' ');
const out = [];
$input.all().forEach((it, i) => {
  const s = sites[i].json;
  const status = it.json.statusCode ?? 0;
  const body = String(it.json.body ?? it.json.data ?? '');
  const title = (body.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1];
  // a real block page is small or has a block-page title; normal pages often just load a reCAPTCHA script
  const blocked = /just a moment|attention required|challenge|access denied|are you a robot|verify you are human/i.test(title)
               || (body.length < 30000 && /cf-chl|challenge-platform|captcha|are you a robot/i.test(body));
  const anchors = [...body.matchAll(/<a\s[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)]
    .map(m => ({ href: m[1], text: decode(m[2].replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim()) }));
  let cands = anchors.filter(a => a.href.includes(s.pattern) && a.text.length >= 12);
  if (cands.length === 0) cands = anchors.filter(a => a.text.length >= 25 && !/^(#|javascript|mailto)/i.test(a.href));
  if (status !== 200 || blocked || cands.length === 0) {
    out.push({ json: { kind: 'site_down', site: s.name, reason: status !== 200 ? 'status ' + status : blocked ? 'blocked' : 'no links found', chat: owner.telegram_id, user_id: owner.user_id } });
    return;
  }
  const baseline = !(Number(counts[s.name]) > 0);      // first successful run for this site: save silently
  const seen = new Set(); let count = 0;
  for (const a of cands) {
    let href = a.href.startsWith('http') ? a.href : s.base + (a.href.startsWith('/') ? '' : '/') + a.href;
    href = href.split('#')[0];
    if (seen.has(href)) continue; seen.add(href);
    const t = a.text.toLowerCase();
    const hits = KEYWORDS.filter(k => t.includes(k));
    const strong = STRONG.filter(k => t.includes(k));
    if (baseline) { if (count >= MAX_BASELINE) break; }
    else { if (hits.length === 0) continue; if (count >= MAX_PER_SITE) break; }
    count++;
    const score = Math.min(95, 45 + 12 * hits.length + 10 * strong.length);
    out.push({ json: { kind: 'job', site: s.name, url: href, title: a.text.slice(0, 300), hits: hits.slice(0, 4), score, notify: !baseline && hits.length > 0, chat: owner.telegram_id, user_id: owner.user_id } });
  }
});
return out;

const strip = (h) => String(h || '').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<nav[\s\S]*?<\/nav>/gi,' ').replace(/<footer[\s\S]*?<\/footer>/gi,' ')
  .replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div|li|h\d|tr)>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/[ \t]+/g,' ').replace(/\n\s*\n+/g,'\n').trim();
return $input.all().map((it, i) => {
  const j = $('Save New').itemMatching(i).json.result;
  const src = $('Is Down').itemMatching(i).json;
  const ok = (it.json.statusCode ?? 0) === 200;
  const text = ok ? strip(it.json.body ?? it.json.data) : '';
  return { json: { code: j.code, id: j.id, chat: src.chat, site: src.site, title: src.title, url: src.url, score: src.score, hits: src.hits, description: text.slice(0, 5000) } };
});

const owner = $('GH Owner').first().json;
const cutoff = Date.now() - 7 * 3600 * 1000;      // last 7 hours; runs every 6 hours, duplicates are blocked by the database
const out = [];
for (const it of $input.all()) {
  const e = it.json;
  if (!e || !e.id || !e.type || !e.created_at) continue;
  if (new Date(e.created_at).getTime() < cutoff) continue;
  const repo = (e.repo && e.repo.name) || '';
  const p = e.payload || {};
  let text = null;
  if (e.type === 'PushEvent') {
    const n = p.size || (p.commits || []).length || 0;
    const msg = ((p.commits || []).slice(-1)[0] || {}).message || '';
    text = `🧑‍💻 GitHub: رفعت ${n || ''} commit على ${repo}` + (msg ? `\n${msg.split('\n')[0].slice(0, 120)}` : '');
  } else if (e.type === 'CreateEvent' && p.ref_type === 'repository') {
    text = `🧑‍💻 GitHub: أنشأت repo جديد ${repo}`;
  } else if (e.type === 'PullRequestEvent') {
    text = `🧑‍💻 GitHub: Pull Request (${p.action}) في ${repo}`;
  } else if (e.type === 'IssuesEvent') {
    text = `🧑‍💻 GitHub: Issue (${p.action}) في ${repo}`;
  }
  if (text) out.push({ json: { key: 'gh:' + e.id, text, chat: owner.telegram_id, user_id: owner.user_id } });
}
return out;
